<?php $e=static fn($value)=>htmlspecialchars((string)$value,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8'); ?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?= $e($site['name']) ?></title><meta name="description" content="<?= $e($site['pages'][0]['fields']['seo_description'] ?? $site['name']) ?>"><?php foreach($site['pages'] as $page): ?><meta name="lifeos-content-version" content="lifeos-version:<?= $e($page['slug']) ?>:<?= (int)$page['published_version'] ?>"><?php endforeach; ?><style>body{margin:0;background:#f5f7fc;color:#182438;font:16px/1.7 system-ui,sans-serif}header,main,footer{max-width:1000px;margin:auto;padding:30px}header{display:flex;justify-content:space-between;gap:24px;align-items:center;border-bottom:1px solid #dfe5ef}header strong{font-size:20px}nav{display:flex;gap:18px;flex-wrap:wrap}a{color:#2563eb;text-decoration:none}section{background:white;padding:40px;border-radius:24px;margin:24px 0;box-shadow:0 12px 40px #15233c08}h1{font-size:clamp(32px,6vw,58px);letter-spacing:-2px;line-height:1.15}h2{font-size:28px;letter-spacing:-.6px}p{white-space:pre-wrap;overflow-wrap:anywhere}img{max-width:100%;max-height:520px;object-fit:cover;border-radius:16px}.eyebrow{font-size:11px;letter-spacing:2px;text-transform:uppercase;color:#2563eb}footer{font-size:12px;color:#68768a}@media(max-width:600px){header{align-items:start;flex-direction:column}header,main,footer{padding:20px}section{padding:25px}}</style></head><body><header><strong><?= $e($site['name']) ?></strong><nav><?php foreach($site['pages'] as $page): ?><a href="#<?= $e($page['slug']) ?>"><?= $e(ucwords(str_replace('-',' ',$page['slug']))) ?></a><?php endforeach; ?></nav></header><main><?php if(!$site['pages']): ?><section><p class="eyebrow">Connected to LifeOS</p><h1>Your website is ready for content.</h1><p>No pages have been published yet.</p></section><?php endif; ?><?php foreach($site['pages'] as $page): ?><section id="<?= $e($page['slug']) ?>"><p class="eyebrow"><?= $e($page['slug']) ?></p><?php foreach($page['fields'] as $key=>$value):if($value===''||$value===null||$value===false||str_starts_with($key,'seo_'))continue; ?><?php if(is_string($value)&&str_starts_with($value,'https://')&&preg_match('/(?:image|photo|cover|logo)/i',$key)): ?><img src="<?= $e($value) ?>" alt="<?= $e(str_replace('_',' ',$key)) ?>"><?php elseif(preg_match('/(?:title|heading)$/',$key)): ?><h2><?= $e($value) ?></h2><?php else: ?><p><?= $e(is_bool($value)?'Yes':$value) ?></p><?php endif; endforeach; ?></section><?php endforeach; ?></main><footer>Managed with LifeOS Gateway · Only published content appears here.</footer></body></html>
